import React,{useState,useEffect,useCallback,useRef,createContext,useContext,useLayoutEffect} from 'react';
import {createRoot} from 'react-dom/client';
import {Heart,Flame,CalendarDays,MessageCircle,UserRound,SlidersHorizontal,ChevronLeft,ChevronRight,X,Star,Zap,Crown,MapPin,ShieldCheck,ArrowUpRight,Send,MoreHorizontal,Settings as SettingsIcon,Check,Plus,LoaderCircle,Gift,Globe,LogOut,Flag,Trash2,Lock,Search,Download,CheckCircle2,Sparkles,Layers,Coffee,Sun,Moon,Sunset,Smile,Image as ImageIcon,Pause,Play,ChevronDown,ArrowRight,Infinity as InfinityIcon,EyeOff,BadgeCheck,Compass,Music,Plane,Dumbbell,Film,PawPrint} from 'lucide-react';
import {api,post,setSession,download} from './api';
import {en,errors} from './i18n';
import './style.css';
import './redesign.css';
import welcomeImage from './assets/welcome-couple.webp';
const Context=createContext();const useApp=()=>useContext(Context);const tg=window.Telegram?.WebApp;const isAdmin=location.pathname.startsWith('/admin');
function Logo({large=false}){return <div className={'brand '+(large?'large':'')}><svg viewBox="0 0 48 48" aria-hidden="true"><defs><linearGradient id="v" x2="1" y2="1"><stop stopColor="#fd739c"/><stop offset=".48" stopColor="#bd50f1"/><stop offset="1" stopColor="#70e5f2"/></linearGradient></defs><path d="M5 14C10 2 22 8 24 16 29 2 46 6 43 18L24 43Z" fill="none" stroke="url(#v)" strokeWidth="6" strokeLinejoin="round"/><path d="m35 1 2 4 4 1-4 2-2 4-2-4-4-2 4-1Z" fill="#caf6ff"/></svg><span>VEYRA<i/></span></div>}
function Button({children,onClick,type='button',className='',disabled=false,...props}){return <button type={type} className={'button '+className} onClick={onClick} disabled={disabled} {...props}>{children}</button>}
function IconButton({icon:Icon,label,onClick,className='',disabled=false}){return <button type="button" className={'icon-button '+className} onClick={onClick} aria-label={label} title={label} disabled={disabled}><Icon size={23}/></button>}
function Empty({icon:Icon=Heart,title,body,children}){return <div className="empty"><div className="empty-orbit"><Icon size={38}/></div><h2>{title}</h2><p>{body}</p>{children}</div>}
function Loading(){const{t}=useApp();return <div className="loading"><LoaderCircle className="spin"/><span>{t('Загрузка…')}</span></div>}
const photoCache=new Map();
function photoSource(id){
 if(!photoCache.has(id)){
  if(photoCache.size>80){const [key,promise]=photoCache.entries().next().value;photoCache.delete(key);promise.then(URL.revokeObjectURL).catch(()=>{});}
  photoCache.set(id,api('/photos/'+id,{raw:true}).then(r=>r.blob()).then(URL.createObjectURL).catch(e=>{photoCache.delete(id);throw e;}));
 }
 return photoCache.get(id);
}
function Photo({id,className='',alt=''}){
 const[url,setUrl]=useState('');const[loaded,setLoaded]=useState(false);
 useEffect(()=>{let alive=true;setUrl('');setLoaded(false);if(id)photoSource(id).then(url=>{if(alive)setUrl(url);}).catch(()=>{});return()=>{alive=false;};},[id]);
 return url?<img src={url} onLoad={()=>setLoaded(true)} className={`${className} photo-image ${loaded?'is-loaded':''}`} alt={alt} draggable={false}/>:<div className={'photo-placeholder '+className} aria-label={alt}><UserRound/></div>;
}

function Sheet({title,children,onClose,className=''}){
 const[closing,setClosing]=useState(false);const panel=useRef(null);const closeTimer=useRef(null);
 const close=()=>{if(closing)return;setClosing(true);closeTimer.current=setTimeout(onClose,160);};
 useEffect(()=>{const previous=document.activeElement;panel.current?.focus();const before=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{clearTimeout(closeTimer.current);document.body.style.overflow=before;previous?.focus?.();};},[]);
 return <div className={'scrim '+(closing?'closing ':'')+className} onClick={close}><section ref={panel} tabIndex={-1} className="sheet" role="dialog" aria-modal="true" aria-label={title} onClick={e=>e.stopPropagation()} onKeyDown={e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const nodes=[...panel.current.querySelectorAll('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]')];const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===panel.current)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}}><span className="sheet-handle"/><header><h2>{title}</h2><IconButton icon={X} label="Close" onClick={close}/></header>{children}</section></div>;
}

function App(){
 const[lang,setLang]=useState(tg?.initDataUnsafe?.user?.language_code?.startsWith('ru')?'ru':'en');const[auth,setAuth]=useState('loading');const[me,setMe]=useState(null);const[tab,setTab]=useState('feed');const[page,setPage]=useState(null);const[toast,setToast]=useState('');const[modal,setModal]=useState(null);const[busy,setBusy]=useState(false);const[openChatId,setOpenChatId]=useState(null);const[chatOpen,setChatOpen]=useState(false);const[badges,setBadges]=useState({likes:0,chats:0});
 const t=useCallback(s=>lang==='en'?(en[s]||s):s,[lang]);const refresh=useCallback(async()=>{const m=await api('/me');setMe(m);setLang(m.user.language);return m;},[]);
 const alert=useCallback(s=>setToast(s),[]);useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(''),4800);return()=>clearTimeout(timer);}},[toast]);
 const run=useCallback(async fn=>{setBusy(true);try{return await fn();}catch(e){alert(lang==='ru'?(errors[e.message]||e.message):(e.message.replaceAll('_',' ').toLowerCase()));}finally{setBusy(false);}},[lang,alert]);
 useEffect(()=>{tg?.ready();tg?.expand();tg?.setHeaderColor?.('#09090f');tg?.setBackgroundColor?.('#09090f');if(!tg?.initData){setAuth('outside');return;}post('/auth',{initData:tg.initData,scope:isAdmin?'admin':'user'}).then(async r=>{setSession(r.token);if(!isAdmin)await refresh();setAuth('ok');}).catch(e=>{setAuth('error');alert(errors[e.message]||e.message);});},[]);
 useEffect(()=>{if(isAdmin||auth!=='ok'||me?.profile?.moderation!=='approved')return;let alive=true;const poll=()=>{if(document.hidden)return;Promise.all([api('/likes'),api('/matches')]).then(([likes,matches])=>{if(alive)setBadges({likes:likes.count,chats:matches.reduce((sum,m)=>sum+m.unread,0)});}).catch(()=>{});};poll();const timer=setInterval(poll,30000);return()=>{alive=false;clearInterval(timer);};},[auth,me?.profile?.moderation,tab]);
 useEffect(()=>{window.scrollTo({top:0,behavior:'instant'});},[page,tab]);
 useEffect(()=>{const viewport=window.visualViewport;const resize=()=>document.documentElement.style.setProperty('--visual-height',`${viewport?.height||window.innerHeight}px`);resize();viewport?.addEventListener('resize',resize);return()=>viewport?.removeEventListener('resize',resize);},[]);
 const switchTab=value=>{setTab(value);setChatOpen(false);setOpenChatId(null);tg?.HapticFeedback?.selectionChanged?.();};
 const approved=me?.profile?.moderation==='approved';const ctx={t,lang,setLang,me,refresh,run,busy,alert,tab,setTab:switchTab,page,setPage,modal,setModal,openChatId,setOpenChatId,setChatOpen,setBadges};
 const shell=isAdmin?'admin-app':chatOpen?'conversation-app':auth==='ok'&&!page&&tab==='feed'&&approved?'feed-app':'member-app';
 return <Context.Provider value={ctx}><div className={'app '+shell}>
 {location.pathname==='/legal'?<Legal/>:auth==='loading'?<div className="boot-screen"><Logo large/><Loading/></div>:auth!=='ok'?<Welcome/>:isAdmin?<Admin/>:!me?<Loading/>:<>
 {!chatOpen&&<header className="topbar"><Logo/><div className="top-actions"><button className="premium-pill" onClick={()=>setPage('premium')}><Crown size={15}/> {new Date(me.user.premium_until)>new Date()?'Premium':'PLUS'}</button><IconButton icon={SettingsIcon} label={t('Настройки')} onClick={()=>setPage('settings')}/></div></header>}
 <main className={chatOpen?'conversation-main':''}><div className="view-enter" key={page||tab}>{page?<><button className="back text-button" onClick={()=>setPage(null)}><ChevronLeft size={19}/>{t('Назад')}</button>{page==='edit'?<ProfileForm/>:page==='premium'?<Premium/>:page==='settings'?<Settings/>:page==='support'?<Support/>:page==='referrals'?<Referrals/>:null}</>:!me.profile?<ProfileForm/>:!approved?<Onboarding/>:tab==='feed'?<Feed/>:tab==='today'?<Today/>:tab==='likes'?<Likes/>:tab==='chats'?<Chats/>:<Profile/>}</div></main>
 {!page&&approved&&!chatOpen&&<nav className="bottom-nav" aria-label={t('Навигация')}>{[['feed',Layers,'Лента'],['today',Sparkles,'Сегодня'],['likes',Heart,'Лайки'],['chats',MessageCircle,'Чаты'],['profile',UserRound,'Профиль']].map(([key,Icon,label])=><button key={key} className={tab===key?'selected':''} onClick={()=>switchTab(key)} aria-label={t(label)} aria-current={tab===key?'page':undefined}><span className="nav-icon"><Icon size={24}/>{badges[key]>0&&<b className="nav-count">{badges[key]>99?'99+':badges[key]}</b>}</span><span>{t(label)}</span><i/></button>)}</nav>}
 </>}
 {modal?.type==='match'&&<MatchCelebration p={modal.profile} onClose={()=>setModal(null)} onChat={()=>{setModal(null);setTab('chats');setOpenChatId(modal.match_id||null);}}/>}
 {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/><span>{toast}</span><button aria-label="Close" onClick={()=>setToast('')}><X size={17}/></button></div>}
 </div></Context.Provider>;
}
function Welcome(){const{t,lang,setLang}=useApp();const[help,setHelp]=useState(false);return <section className="welcome welcome-photo" style={{'--welcome-image':`url(${welcomeImage})`}}><header><Logo/><button className="language-button" onClick={()=>setLang(lang==='ru'?'en':'ru')}><Globe size={15}/>{lang.toUpperCase()}</button></header><div className="welcome-location"><Globe size={16}/>{t('Знакомства без границ')}</div><div className="welcome-copy"><span className="eyebrow">A LITTLE CLOSER</span><h1>{t('Твоя следующая')}<em>{t('история любви')}</em><Heart size={30}/></h1><p>{t('Настоящие люди рядом с вами. Новые знакомства, отношения и приятные встречи.')}</p><div className="welcome-promises">{[[UserRound,'Живые знакомства'],[MapPin,'Люди рядом'],[Heart,'Взаимная симпатия']].map(([Icon,label])=><div key={label}><span><Icon size={21}/></span><small>{t(label)}</small></div>)}</div><a className="button primary full" href={'https://t.me/'+(isAdmin?'VeyraAdminBot':'VeyraAppBot')}><Heart size={22} fill="currentColor"/>{t('Открыть в Telegram')}<ArrowRight size={20}/></a><div className="welcome-links"><button className="button secondary" onClick={()=>setHelp(true)}><Play size={16}/>{t('Как это работает')}</button><a className="button secondary" href="/legal"><ShieldCheck size={16}/>{t('Правила')}</a></div><div className="adult-note"><strong>18+</strong><small>{t('Только для совершеннолетних. Уважение, безопасность и взаимное согласие.')}</small></div></div>{help&&<Sheet title={t('Как это работает')} onClose={()=>setHelp(false)}><div className="how-steps">{[['1','Создай анкету','Расскажи о себе и добавь свои фотографии.'],['2','Пройди проверку','Каждая анкета проходит ручную модерацию.'],['3','Найди симпатию','Взаимный лайк открывает ваш личный чат.']].map(([n,title,body])=><div key={n}><b>{n}</b><div><h3>{t(title)}</h3><p>{t(body)}</p></div></div>)}</div></Sheet>}</section>;}
function MatchCelebration({p,onClose,onChat}){const{t,me}=useApp();return <Sheet title={t('Взаимная симпатия!')} onClose={onClose} className="match-scene"><div className="match-glow"/><div className="match-sparks" aria-hidden="true">{Array.from({length:9},(_,i)=><Heart key={i} size={10+i%3*6} style={{'--i':i}}/>)}</div><div className="match-title"><div className="double-heart"><Heart/><Heart/></div><h1>{t('У вас')} <em>{t('мэтч!')}</em></h1><p>{t('Вы понравились друг другу')}</p></div><div className="match-people"><div><Photo id={me.photos[0]?.id} alt={me.profile.name}/><h3>{me.profile.name}</h3></div><span className="match-heart"><Heart fill="currentColor"/></span><div><Photo id={p?.photos[0]} alt={p?.name||''}/><h3>{p?.name||'VEYRA'}</h3></div></div><div className="match-note"><Sparkles/><span>{t('Возможно, это начало чего-то особенного')}</span></div><Button className="primary full" onClick={onChat}><MessageCircle fill="currentColor" size={21}/>{t('Перейти в чаты')}<ArrowRight size={19}/></Button><Button className="secondary full" onClick={onClose}><Search size={20}/>{t('Продолжить поиск')}</Button></Sheet>;}

function Field({label,children}){return <label className="field"><span>{label}</span>{React.cloneElement(children,{'aria-label':children.props['aria-label']||label})}</label>}
const genders=[['man','Мужчина'],['woman','Женщина'],['other','Другое']];
function ProfileForm(){const{t,me,refresh,run,busy,setPage,alert}=useApp();const p=me?.profile;const[f,setF]=useState(p?{...p,birth_date:String(p.birth_date).slice(0,10),consent:true}:{name:me?.user.first_name||'',birth_date:'',gender:'man',looking_for:['woman'],bio:'',interests:[],goal:'relationship',city:'',country:'',lat:null,lon:null,min_age:18,max_age:45,radius_km:100,consent:false});const[q,setQ]=useState('');const[places,setPlaces]=useState([]);const upd=(k,v)=>setF(x=>({...x,[k]:v}));
 const locate=()=>{navigator.geolocation?navigator.geolocation.getCurrentPosition(pos=>run(async()=>{const r=await api(`/geo?lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`);if(r[0]){setF(x=>({...x,...r[0]}));setPlaces([]);}}),()=>alert(t('Найти город')),{timeout:15000,maximumAge:300000}):alert(t('Найти город'));};
 return <section className="form-page"><span className="eyebrow">YOUR STORY</span><h1>{t(p?'Редактировать':'Сначала — немного о тебе')}</h1><p className="page-subtitle">{t('Расскажи о себе, чтобы мы подобрали интересных людей.')}</p><div className="onboarding-progress"><span className="active"/><i/><span/><i/><span/><small>{t('Анкета → Фото → Проверка')}</small></div><form onSubmit={e=>{e.preventDefault();run(async()=>{await api('/profile',{method:'PUT',body:f});await refresh();setPage(null);});}}>
 <div className="columns"><Field label={t('Имя')}><input value={f.name} maxLength={50} required onChange={e=>upd('name',e.target.value)}/></Field><Field label={t('Дата рождения')}><input type="date" value={f.birth_date} required onChange={e=>upd('birth_date',e.target.value)}/></Field></div>
 <Field label={t('Я')}><select value={f.gender} onChange={e=>{const gender=e.target.value;setF(x=>({...x,gender,...(!p?{looking_for:gender==='man'?['woman']:gender==='woman'?['man']:['man','woman','other']}:{})}));}}>{genders.map(([k,v])=><option key={k} value={k}>{t(v)}</option>)}</select></Field>
 <div className="field"><span>{t('Ищу')}</span><div className="chips">{genders.map(([k,v])=><button type="button" key={k} className={'chip '+(f.looking_for.includes(k)?'active':'')} onClick={()=>upd('looking_for',f.looking_for.includes(k)?f.looking_for.filter(x=>x!==k):[...f.looking_for,k])}>{t(v)}</button>)}</div></div>
 <Field label={t('О себе')}><textarea value={f.bio} maxLength={1000} rows={4} onChange={e=>upd('bio',e.target.value)}/></Field><Field label={t('Интересы через запятую')}><input defaultValue={f.interests.join(', ')} onChange={e=>upd('interests',e.target.value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,10))}/></Field>
 <Field label={t('Цель знакомства')}><select value={f.goal} onChange={e=>upd('goal',e.target.value)}>{[['relationship','Отношения'],['dating','Свидания'],['friends','Дружба'],['unsure','Пока не знаю']].map(([k,v])=><option key={k} value={k}>{t(v)}</option>)}</select></Field>
 <div className="location-box"><span className="muted">{t('Город')}</span>{f.city&&<p><MapPin size={17}/>{f.city}, {f.country}</p>}<div className="inline"><input aria-label={t('Город')} value={q} onChange={e=>setQ(e.target.value)} placeholder={t('Найти город')}/><IconButton icon={Search} label={t('Найти город')} onClick={()=>run(async()=>setPlaces(await api('/geo?q='+encodeURIComponent(q))))}/></div>{places.map((place,i)=><button key={i} type="button" className="place" onClick={()=>{setF(x=>({...x,...place}));setPlaces([]);setQ('');}}>{place.label}</button>)}<button type="button" className="text-button" onClick={locate}><MapPin size={16}/>{t('Определить местоположение')}</button></div>
 <div className="columns"><Field label={t('Возраст от')}><input type="number" min="18" max="110" value={f.min_age} onChange={e=>upd('min_age',+e.target.value)}/></Field><Field label={t('Возраст до')}><input type="number" min={f.min_age} max="110" value={f.max_age} onChange={e=>upd('max_age',+e.target.value)}/></Field></div>
 <Field label={t('Расстояние, км')}><input type="number" min="1" max="20000" value={f.radius_km} onChange={e=>upd('radius_km',+e.target.value)}/></Field>
 {p&&<><h2 className="section-label"><ImageIcon size={20}/>{t('Мои фотографии')}</h2><PhotoManager/></>}<label className="check"><input type="checkbox" checked={f.consent} required onChange={e=>upd('consent',e.target.checked)}/><span>{t('Мне исполнилось 18 лет, я принимаю условия и политику конфиденциальности')} · <a href="/legal" target="_blank" rel="noreferrer">18+</a></span></label>
 <Button type="submit" className="primary full" disabled={busy||!f.city||!f.consent}>{t('Сохранить анкету')}<ChevronRight size={18}/></Button></form></section>;
}
function Onboarding(){const{t,me,setPage,refresh,run,busy}=useApp();const status=me.profile.moderation;return <section><div className="step-line"><span className="done">01</span><i/><span className={me.photos.length?'done':''}>02</span><i/><span className={status==='pending'?'done':''}>03</span></div><h1>{t(status==='pending'?'Анкета на проверке':status==='rejected'?'Нужно поправить анкету':'Добавь свои фотографии')}</h1><p className="muted">{t(status==='pending'?'Проверяем фото и анкету вручную. Сообщим результат в Telegram.':'От 1 до 6 фотографий. Первое фото — обложка.')}</p>{me.profile.moderation_reason&&<p className="notice">{me.profile.moderation_reason}</p>}<PhotoManager/><Button className="secondary full" onClick={()=>setPage('edit')}>{t('Редактировать')}</Button>{status!=='pending'&&<Button className="primary full" disabled={busy||!me.photos.length} onClick={()=>run(async()=>{await post('/profile/submit');await refresh();})}>{t('Отправить на проверку')}<ShieldCheck size={18}/></Button>}{status==='pending'&&<Button className="primary full" onClick={()=>run(refresh)}>{t('Обновить')}</Button>}<button className="text-button" onClick={()=>setPage('support')}>{t('Поддержка')}</button></section>}
function PhotoManager(){const{t,me,run,refresh}=useApp();return <div className="photo-grid">{me.photos.map(p=><div className="photo-tile" key={p.id}><Photo id={p.id}/><IconButton icon={X} label={t('Удалить')} onClick={()=>run(async()=>{await api('/photos/'+p.id,{method:'DELETE'});await refresh();})}/></div>)}{me.photos.length<6&&<label className="photo-upload"><Plus/><span>{t('Загрузить фото')}</span><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>{const file=e.target.files[0];if(!file)return;run(async()=>{const form=new FormData();form.append('photo',file);await post('/photos',form);await refresh();});e.target.value='';}}/></label>}</div>}
function Card({p,onReact}){
 const{t,run,setModal,busy}=useApp();const[index,setIndex]=useState(0);const[report,setReport]=useState(false);const[prematch,setPrematch]=useState(false);const[msg,setMsg]=useState('');const[phase,setPhase]=useState('');const gesture=useRef(null);const[drag,setDrag]=useState(0);const suppressClick=useRef(false);const sending=useRef(false);
 useEffect(()=>{setIndex(0);setDrag(0);setPhase('');gesture.current=null;},[p.id]);
 const act=kind=>{if(sending.current)return;sending.current=true;run(async()=>{setPhase('leaving-'+kind);try{const [r]=await Promise.all([post('/reactions',{target:String(p.id),kind,...(msg?{message:msg}:{})}),new Promise(resolve=>setTimeout(resolve,230))]);setPrematch(false);setMsg('');tg?.HapticFeedback?.impactOccurred?.('light');if(r.matched)setModal({type:'match',profile:p,match_id:r.match_id});await onReact();}finally{setPhase('');sending.current=false;}});};
 const pointerDown=e=>{if(busy||sending.current||e.button!==0||(e.target.closest('button,a,input,textarea')&&!e.target.closest('.photo-controls')))return;suppressClick.current=false;gesture.current={x:e.clientX,y:e.clientY};e.currentTarget.setPointerCapture(e.pointerId);};
 const pointerMove=e=>{if(!gesture.current)return;const dx=e.clientX-gesture.current.x,dy=e.clientY-gesture.current.y;setDrag(Math.abs(dx)>Math.abs(dy)*1.2?dx:0);};
 const pointerUp=e=>{if(!gesture.current)return;const dx=e.clientX-gesture.current.x,dy=e.clientY-gesture.current.y;gesture.current=null;setDrag(0);suppressClick.current=Math.abs(dx)>25&&Math.abs(dx)>Math.abs(dy)*1.2;if(Math.abs(dx)>90&&Math.abs(dx)>Math.abs(dy)*1.2&&!busy)act(dx>0?'like':'pass');};
 return <><article key={p.id} className={'dating-card swipe-card '+phase+(drag?' dragging':'')} onClickCapture={e=>{if(suppressClick.current){e.preventDefault();e.stopPropagation();suppressClick.current=false;}}} onPointerDown={pointerDown} onPointerMove={pointerMove} onPointerUp={pointerUp} onPointerCancel={()=>{gesture.current=null;setDrag(0);}} style={drag?{transform:`translateX(${Math.max(-170,Math.min(170,drag))}px) rotate(${drag/30}deg)`}:undefined}>
 <Photo id={p.photos[index]} alt={p.name} className="cover"/>
 {Math.abs(drag)>25&&<span className={'swipe-label '+(drag>0?'yes':'no')}>{t(drag>0?'Нравится':'Пропустить')}</span>}
 <div className="photo-dots">{p.photos.map((x,i)=><button key={x} aria-label={t('Фото')+' '+(i+1)} className={i===index?'on':''} onClick={()=>setIndex(i)}/>)}</div>
 <div className="card-top"><span className="card-status"><BadgeCheck size={14}/>{t('Анкета проверена')}</span><div className="inline"><span className="photo-counter">{index+1}/{p.photos.length}</span><IconButton icon={MoreHorizontal} label={t('Пожаловаться')} onClick={()=>setReport(true)}/></div></div>
 {p.photos.length>1&&<div className="photo-controls"><button aria-label={t('Предыдущее фото')} onClick={()=>setIndex((index+p.photos.length-1)%p.photos.length)}/><button aria-label={t('Следующее фото')} onClick={()=>setIndex((index+1)%p.photos.length)}/></div>}
 <div className="card-info">{p.activity&&<span className="today-badge"><span/>{t('Свободен сегодня')}</span>}<h2>{p.name}<span>, {p.age}</span><BadgeCheck size={21} className="approved-badge" aria-label={t('Анкета проверена')}/></h2><p className="card-location"><MapPin size={15}/>{p.city}{p.distance_km?' · ~'+p.distance_km+' '+t('км'):''}</p><div className="tags goal-tags"><span><Heart size={12}/>{t(({relationship:'Отношения',dating:'Свидания',friends:'Дружба',unsure:'Пока не знаю'})[p.goal]||'Знакомства')}</span></div>{p.interests.length>0&&<div className="tags interest-tags">{p.interests.slice(0,5).map(x=><span key={x}>{x}</span>)}</div>}{p.bio&&<p className="bio">{p.bio}</p>}</div>
 </article><div className="reaction-bar"><IconButton icon={X} className="pass" label={t('Пропустить')} onClick={()=>act('pass')} disabled={busy}/><IconButton icon={Heart} className="like" label={t('Нравится')} onClick={()=>act('like')} disabled={busy}/><IconButton icon={Star} className="super" label="Super Like" onClick={()=>act('super')} disabled={busy}/><IconButton icon={MessageCircle} className="prematch" label={t('Сообщение до мэтча')} onClick={()=>setPrematch(true)}/></div>
 {report&&<Report target={p.id} onClose={()=>setReport(false)}/>}{prematch&&<Sheet title={t('Сказать привет')} onClose={()=>setPrematch(false)}><p>{t('Сообщение до мэтча')} · 140</p><textarea aria-label={t('Сообщение до мэтча')} maxLength={140} value={msg} onChange={e=>setMsg(e.target.value)} rows={3}/><Button className="primary full" disabled={!msg.trim()||busy} onClick={()=>act('like')}>{t('Отправить')}<Send size={18}/></Button></Sheet>}</>;
}

function Feed(){
 const{t,run,me,setPage}=useApp();const[filters,setFilters]=useState(false);const[data,setData]=useState(null);const[error,setError]=useState(false);
 const load=useCallback(async()=>{setError(false);try{setData(await api('/feed'));}catch(e){setError(true);throw e;}},[]);useEffect(()=>{run(load);},[load]);
 return <section className="feed-surface"><div className="discovery-heading"><div><span className="location-line"><MapPin size={14}/>{me.profile.city}<ChevronDown size={13}/></span><h1>{t('Лента')}</h1><p>{t('Знакомьтесь с интересными людьми рядом')}</p></div><IconButton icon={SlidersHorizontal} label={t('Фильтры')} onClick={()=>setFilters(true)}/></div>{me.user.paused&&<button className="pause-note" onClick={()=>setPage('settings')}><Pause size={14}/>{t('Ваша анкета на паузе')}</button>}
 {data?.profiles.length?<Card p={data.profiles[0]} onReact={load}/>:data?<Empty icon={data.limited?Crown:Heart} title={t(data.limited?'На сегодня всё':'Пока здесь тихо')} body={t(data.limited?'Ты посмотрел 30 анкет. Возвращайся завтра или открой Premium.':'Подходящие анкеты появятся, когда участники рядом пройдут модерацию. Можно расширить радиус в профиле.')}><Button className="secondary" onClick={()=>data.limited?setPage('premium'):run(load)}>{t(data.limited?'Премиум':'Обновить')}</Button></Empty>:error?<Button onClick={()=>run(load)}>{t('Попробовать ещё')}</Button>:<Loading/>}{filters&&<Filters onClose={()=>setFilters(false)} onSaved={load}/>}</section>;
}
function Filters({onClose,onSaved}){const{t,me,run,refresh,busy}=useApp();const[f,setF]=useState({min_age:me.profile.min_age,max_age:me.profile.max_age,radius_km:me.profile.radius_km});return <Sheet title={t('Фильтры')} onClose={onClose}><p>{t('Найди тех, с кем вы на одной волне')}</p>{[['min_age','Возраст от'],['max_age','Возраст до'],['radius_km','Расстояние, км']].map(([k,l])=><Field key={k} label={t(l)}><input type="number" min={k==='radius_km'?1:18} max={k==='radius_km'?20000:110} value={f[k]} onChange={e=>setF({...f,[k]:+e.target.value})}/></Field>)}<Button className="primary full" disabled={busy} onClick={()=>run(async()=>{await api('/preferences',{method:'PATCH',body:f});await refresh();onClose();await onSaved?.();})}>{t('Сохранить')}<Check size={18}/></Button></Sheet>;}

const activities=[['coffee','Кофе'],['walk','Прогулка'],['dinner','Ужин'],['cinema','Кино'],['ride','Покататься'],['party','Потусоваться'],['meet','Просто познакомиться']];
function Today(){
 const{t,me,run,refresh,busy,setModal}=useApp();const[activity,setActivity]=useState(me.today?.activity||'coffee');const[time,setTime]=useState(me.today?.time_slot||'evening');const[data,setData]=useState(null);const[selected,setSelected]=useState(null);const[filters,setFilters]=useState(false);const[pendingAvailability,setPendingAvailability]=useState(null);
 const load=useCallback(async()=>setData(await api('/feed?today=true&limit=6')),[]);useEffect(()=>{run(load);},[load]);
 const save=async()=>{const d=new Date();d.setHours(24,0,0,0);await api('/today',{method:'PUT',body:{activity,time_slot:time,expires_at:d.toISOString()}});await refresh();};
 const toggleAvailability=checked=>{setPendingAvailability(checked);run(async()=>{try{if(checked)await save();else{await api('/today',{method:'DELETE'});await refresh();}}finally{setPendingAvailability(null);}});};
 const like=p=>run(async()=>{const r=await post('/reactions',{target:String(p.id),kind:'like'});if(r.matched)setModal({type:'match',profile:p,match_id:r.match_id});await load();});
 return <section className="today-page"><div className="discovery-heading"><div><span className="location-line"><MapPin size={14}/>{me.profile.city}</span><h1>{t('Сегодня')}</h1><p>{t('Люди, которые хотят провести время вместе')}</p></div><IconButton icon={SlidersHorizontal} label={t('Фильтры')} onClick={()=>setFilters(true)}/></div>
 <div className="today-plan"><label className="availability-toggle"><span><CalendarDays size={19}/>{t('Я свободен сегодня')}</span><input type="checkbox" role="switch" checked={pendingAvailability??!!me.today} disabled={busy||pendingAvailability!==null} aria-busy={pendingAvailability!==null} onChange={e=>toggleAvailability(e.target.checked)}/></label><div className="segmented time-slots">{[['now',Sun,'Сейчас'],['evening',Sunset,'Вечером'],['after21',Moon,'После 21:00']].map(([key,Icon,label])=><button key={key} className={time===key?'active':''} onClick={()=>setTime(key)}><Icon size={17}/>{t(label)}</button>)}</div><div className="chips activity-options">{activities.map(([k,v])=><button key={k} className={'chip '+(activity===k?'active':'')} onClick={()=>setActivity(k)}>{t(v)}</button>)}</div>{(!me.today||activity!==me.today.activity||time!==me.today.time_slot)&&<Button className="primary full" disabled={busy} onClick={()=>run(save)}>{t(me.today?'Сохранить':'Показать мой план')}<ArrowRight size={17}/></Button>}<small className="muted">{t('Статус действует до полуночи по времени устройства.')}</small></div>
 {!data?<Loading/>:data.profiles.length?<div className="today-list">{data.profiles.map(p=><article className="today-person" key={p.id}><button className="today-photo" onClick={()=>setSelected(p)} aria-label={p.name}><Photo id={p.photos[0]} alt={p.name}/><span><ImageIcon size={12}/>{p.photos.length}</span></button><div className="today-person-info"><button className="name-button" onClick={()=>setSelected(p)}><h3>{p.name}, {p.age}<BadgeCheck size={16}/></h3></button><p className="mini-location"><MapPin size={12}/>{p.city}</p><span className="today-badge"><span/>{t('Свободен сегодня')}</span><small className="time-label">{t(({now:'Сейчас',evening:'Вечером',after21:'После 21:00'})[p.time_slot]||'Сегодня')}</small><p className="today-bio">{p.bio}</p><div className="tags"><span><Coffee size={12}/>{t(activities.find(x=>x[0]===p.activity)?.[1]||'Сегодня')}</span></div></div><div className="today-actions"><IconButton icon={Heart} className="like" label={t('Нравится')+' '+p.name} disabled={busy} onClick={()=>like(p)}/><IconButton icon={MessageCircle} label={t('Открыть анкету')+' '+p.name} onClick={()=>setSelected(p)}/></div></article>)}</div>:<Empty icon={Sparkles} title={t(data.limited?'На сегодня всё':'Пока здесь тихо')} body={t('Поделись планом — новые знакомства начинаются спонтанно.')}><Button className="secondary" onClick={()=>run(load)}>{t('Обновить')}</Button></Empty>}
 {selected&&<Sheet title={selected.name} className="profile-preview" onClose={()=>setSelected(null)}><Card p={selected} onReact={async()=>{setSelected(null);await load();}}/></Sheet>}{filters&&<Filters onClose={()=>setFilters(false)} onSaved={load}/>}</section>;
}

function Likes(){
 const{t,run,setPage,setBadges}=useApp();const[data,setData]=useState(null);const[selected,setSelected]=useState(null);const load=async()=>{const d=await api('/likes');setData(d);setBadges(x=>({...x,likes:d.count}));};useEffect(()=>{run(load);},[]);
 return <section className="likes-page"><div className="page-heading"><div><h1>{t('Лайки')}</h1><p>{t('Вы кому-то понравились. Ваша история может начаться здесь.')}</p></div><span className="heading-heart"><Heart fill="currentColor"/></span></div>{!data?<Loading/>:data.count===0?<Empty title={t('Симпатии появятся здесь')} body={t('Заглядывай в ленту и знакомься.')}/>:<><div className="likes-meta"><span><Heart size={17} fill="currentColor"/> {data.count} {t('симпатий')}</span><span className="new-likes">{t('Новые лайки')}<i/></span></div>{data.locked?<><div className="likes-paywall"><div className="paywall-copy"><Crown size={28} fill="currentColor"/><h2>{t('Вас лайкнули')}<em>{data.count} {t('человек')}</em></h2><p>{t('Открой Premium, чтобы увидеть, кому ты понравился.')}</p><Button className="primary" onClick={()=>setPage('premium')}><Crown size={17}/>{t('Открыть Premium')}<ChevronRight size={16}/></Button></div><div className="locked-cards" aria-hidden="true"><div><UserRound/></div><div><UserRound/></div><div><Lock/></div></div></div><div className="likes-grid locked-grid">{Array.from({length:Math.min(data.count,6)},(_,i)=><button className="like-tile locked-tile" key={i} onClick={()=>setPage('premium')} aria-label={t('Открыть Premium')}><UserRound className="anonymous-portrait"/><span className="lock-icon"><Lock size={22}/></span><span className="premium-tag"><Crown size={13}/> Premium</span></button>)}</div></>:<div className="likes-grid">{data.profiles.map(p=><button className="like-tile" key={p.id} onClick={()=>setSelected(p)}><Photo id={p.photos[0]} alt={p.name}/><span className={'tile-heart '+(p.reaction==='super'?'super':'')}><Heart size={18} fill="currentColor"/></span><div><h3>{p.name}, {p.age}<BadgeCheck size={14}/></h3><p><MapPin size={12}/>{p.city}</p>{p.message&&<small><MessageCircle size={12}/>{t('Вам написали')}</small>}</div></button>)}</div>}</>}{selected&&<Sheet title={selected.name} className="profile-preview" onClose={()=>setSelected(null)}>{selected.message&&<p className="notice">{selected.message}</p>}<Card p={selected} onReact={async()=>{setSelected(null);await load();}}/></Sheet>}</section>;
}

function Chats(){
 const{t,lang,run,openChatId,setOpenChatId,setBadges}=useApp();const[rows,setRows]=useState(null);const[chat,setChat]=useState(null);const[search,setSearch]=useState('');
 const load=useCallback(async()=>{const values=await api('/matches');values.sort((a,b)=>new Date(b.last?.created_at||b.created_at)-new Date(a.last?.created_at||a.created_at));setRows(values);setBadges(x=>({...x,chats:values.reduce((n,m)=>n+m.unread,0)}));},[]);
 useEffect(()=>{run(load);const timer=setInterval(()=>{if(!document.hidden)load().catch(()=>{});},12000);return()=>clearInterval(timer);},[load]);
 useEffect(()=>{if(openChatId&&rows){const next=rows.find(m=>m.id===openChatId);if(next){setChat(next);setOpenChatId(null);}}},[openChatId,rows]);
 if(chat)return <Chat chat={chat} onBack={()=>{setChat(null);run(load);}}/>;
 const visible=rows?.filter(m=>(m.profile.name+' '+(m.last?.body||'')).toLocaleLowerCase().includes(search.toLocaleLowerCase()));
 return <section className="chats-page"><div className="page-heading"><div><h1>{t('Чаты')}</h1><p>{t('Одно сообщение может изменить всё')}</p></div><MessageCircle className="heading-heart"/></div><label className="chat-search"><Search size={19}/><input placeholder={t('Поиск по чатам…')} aria-label={t('Поиск по чатам…')} value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button onClick={()=>setSearch('')} aria-label={t('Очистить поиск')}><X size={16}/></button>}</label>{rows===null?<Loading/>:visible.length?visible.map(m=><button className="chat-row" key={m.id} onClick={()=>setChat(m)}><span className="chat-avatar"><Photo id={m.profile.photos[0]} alt=""/>{m.unread>0&&<i/>}</span><div className="chat-summary"><h3>{m.profile.name}<span>, {m.profile.age}</span></h3><p>{m.last?.body||t('Сказать привет')}</p></div><div className="chat-meta"><time>{new Date(m.last?.created_at||m.created_at).toLocaleDateString()===new Date().toLocaleDateString()?new Date(m.last?.created_at||m.created_at).toLocaleTimeString(lang==='ru'?'ru-RU':'en-GB',{hour:'2-digit',minute:'2-digit'}):new Date(m.last?.created_at||m.created_at).toLocaleDateString(lang==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'short'})}</time>{m.unread>0?<span className="count">{m.unread}</span>:<ChevronRight size={17}/>}</div></button>):<Empty icon={MessageCircle} title={t(search?'Ничего не найдено':'Пока нет переписок')} body={t(search?'Попробуй другое имя или слово из сообщения.':'Взаимный лайк открывает чат.')}/>}</section>;
}

function Chat({chat,onBack}){
 const{t,lang,me,run,busy,alert,setChatOpen,setBadges}=useApp();const[data,setData]=useState(null);const[text,setText]=useState('');const[menu,setMenu]=useState(false);const[report,setReport]=useState(false);const[older,setOlder]=useState([]);const[more,setMore]=useState(true);const[emoji,setEmoji]=useState(false);const list=useRef(null);const first=useRef(true);const nearBottom=useRef(true);const input=useRef(null);const readMarked=useRef(false);
 const load=useCallback(async()=>{const d=await api('/matches/'+chat.id+'/messages');setData(d);await post('/matches/'+chat.id+'/read');if(!readMarked.current){setBadges(x=>({...x,chats:Math.max(0,x.chats-chat.unread)}));readMarked.current=true;}},[chat.id]);
 useLayoutEffect(()=>{setChatOpen(true);window.scrollTo({top:0,behavior:'instant'});return()=>setChatOpen(false);},[]);
 useEffect(()=>{run(load);const timer=setInterval(()=>{if(!document.hidden)load().catch(()=>{});},4000);return()=>clearInterval(timer);},[load]);
 const latest=data?.messages.at(-1)?.id;
 useLayoutEffect(()=>{if(!list.current||!data)return;if(first.current||nearBottom.current){list.current.scrollTo({top:list.current.scrollHeight,behavior:first.current||window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});first.current=false;}},[latest]);
 const end=()=>{if(confirm(t('Завершить этот чат? Повторное общение не восстановится автоматически.')))run(async()=>{await api('/matches/'+chat.id,{method:'DELETE'});onBack();});};
 const send=()=>{if(!text.trim()||busy)return;const body=text;run(async()=>{await post('/matches/'+chat.id+'/messages',{body,client_id:crypto.randomUUID()});setText('');setEmoji(false);nearBottom.current=true;await load();input.current?.focus();});};
 const messages=[...older,...(data?.messages||[])].filter((v,i,a)=>a.findIndex(x=>x.id===v.id)===i);
 return <section className="chat-view"><header className="chat-header"><IconButton icon={ChevronLeft} label={t('Назад')} onClick={onBack}/><Photo id={chat.profile.photos[0]}/><div><h3>{chat.profile.name}</h3><small>{t('Ваша взаимная симпатия')}</small></div><IconButton icon={MoreHorizontal} label={t('Настройки')} onClick={()=>setMenu(!menu)}/></header>
 {menu&&<div className="chat-menu"><Button className="secondary" onClick={()=>run(async()=>{const r=await post('/matches/'+chat.id+'/exchange');setData(x=>({...x,exchange:r}));alert(t('Согласие отправлено'));})}><Send size={14}/>{t('Обменяться Telegram')}</Button><Button onClick={()=>setReport(true)}>{t('Пожаловаться')}</Button><Button className="danger" onClick={end}>{t('Завершить общение')}</Button></div>}
 {data?.exchange?.mutual?(data.exchange.username?<a className="exchange-link" href={'https://t.me/'+data.exchange.username} target="_blank" rel="noreferrer">@{data.exchange.username}<ArrowUpRight size={15}/></a>:<p className="notice">{t('У собеседника нет публичного username. Продолжайте общение здесь.')}</p>):<p className="chat-notice"><Lock size={12}/>{t('Telegram откроется после взаимного согласия.')}</p>}
 <div className="messages" ref={list} onScroll={()=>{nearBottom.current=list.current.scrollHeight-list.current.scrollTop-list.current.clientHeight<80;}}>{data?.has_more&&more&&<button className="text-button older-messages" disabled={busy} onClick={()=>run(async()=>{const height=list.current.scrollHeight;const before=older[0]?.created_at||data.messages[0].created_at;const d=await api('/matches/'+chat.id+'/messages?before='+encodeURIComponent(before));setOlder(x=>[...d.messages,...x]);setMore(d.has_more);requestAnimationFrame(()=>{list.current.scrollTop=list.current.scrollHeight-height;});})}>{t('Показать предыдущие')}</button>}{messages.map((m,i)=>{const mine=String(m.sender)===String(me.user.id);const day=new Date(m.created_at).toLocaleDateString();const separator=i===0||new Date(messages[i-1].created_at).toLocaleDateString()!==day;return <React.Fragment key={m.id}>{separator&&<div className="message-day">{day===new Date().toLocaleDateString()?t('Сегодня'):new Date(m.created_at).toLocaleDateString(lang==='ru'?'ru-RU':'en-GB',{day:'numeric',month:'long'})}</div>}<div className={'message-row '+(mine?'mine':'')}>{!mine&&<Photo id={chat.profile.photos[0]} className="message-avatar"/>}<div className={'bubble '+(mine?'mine':'')}><p>{m.body}</p><small>{new Date(m.created_at).toLocaleTimeString(lang==='ru'?'ru-RU':'en-GB',{hour:'2-digit',minute:'2-digit'})}{mine&&<span className={'delivery '+(m.read_at?'read':'')}><Check size={13}/>{m.read_at&&<Check size={13}/>}</span>}</small></div></div></React.Fragment>;})}{data&&!messages.length&&<div className="first-message"><Heart size={38}/><h3>{t('Начни с одного привет')}</h3><p>{t('Ваша симпатия уже взаимна')}</p></div>}</div>
 {emoji&&<div className="emoji-picker">{['😊','💖','👋','☕','✨','😍','😂','🔥'].map(value=><button key={value} onClick={()=>{setText(x=>(x+value).slice(0,2000));input.current?.focus();}}>{value}</button>)}</div>}
 <form className="compose" onSubmit={e=>{e.preventDefault();send();}}><div className="compose-field"><input ref={input} aria-label={t('Сообщение…')} placeholder={t('Сообщение…')} maxLength={2000} value={text} onChange={e=>setText(e.target.value)}/><button type="button" className="emoji-button" aria-label={t('Эмодзи')} onClick={()=>setEmoji(!emoji)}><Smile size={22}/></button></div><button className="send-button" disabled={!text.trim()||busy} aria-label={t('Отправить')}><Send size={22}/></button></form>{report&&<Report target={chat.profile.id} onClose={()=>setReport(false)} onBlock={onBack}/>}</section>;
}

function Report({target,onClose,onBlock}){const{t,run,busy,alert}=useApp();const[reason,setReason]=useState('fake');const[details,setDetails]=useState('');return <Sheet title={t('Пожаловаться')} onClose={onClose}><Field label={t('Причина жалобы')}><select value={reason} onChange={e=>setReason(e.target.value)}>{[['underage','Несовершеннолетний'],['fake','Фейковый профиль'],['harassment','Оскорбления'],['spam','Спам'],['explicit','Откровенный контент'],['other','Другое']].map(([k,v])=><option key={k} value={k}>{t(v)}</option>)}</select></Field><Field label={t('Комментарий')}><textarea value={details} maxLength={2000} onChange={e=>setDetails(e.target.value)}/></Field><Button className="primary full" disabled={busy} onClick={()=>run(async()=>{await post('/reports',{target:String(target),reason,details});alert(t('Готово'));onClose();})}>{t('Отправить жалобу')}</Button><Button className="danger full" onClick={()=>{if(confirm(t('Заблокировать пользователя и закрыть чат?')))run(async()=>{await post('/blocks',{target:String(target)});onClose();onBlock?.();});}}>{t('Заблокировать')}</Button></Sheet>}
function PauseToggle(){const{t,me,run,refresh,busy}=useApp();const[pending,setPending]=useState(null);const toggle=paused=>{setPending(paused);run(async()=>{try{await api('/profile/visibility',{method:'PATCH',body:{paused}});await refresh();}finally{setPending(null);}});};return <label className="setting-row pause-setting"><span className="menu-symbol violet"><Pause size={22}/></span><span>{t('Пауза анкеты')}<small>{t('Временно скрыть профиль из поиска')}</small></span><input type="checkbox" role="switch" checked={pending??!!me.user.paused} disabled={busy||pending!==null} aria-busy={pending!==null} onChange={e=>toggle(e.target.checked)}/></label>;}
function Profile(){const{t,me,setPage}=useApp();const[photo,setPhoto]=useState(null);const[info,setInfo]=useState(false);const birth=new Date(me.profile.birth_date);const now=new Date();let age=now.getFullYear()-birth.getUTCFullYear();if(now.getMonth()<birth.getUTCMonth()||(now.getMonth()===birth.getUTCMonth()&&now.getDate()<birth.getUTCDate()))age--;
 return <section className="profile-page"><div className="page-heading"><h1>{t('Профиль')}</h1></div><div className="my-profile"><button className="profile-avatar" onClick={()=>setPhoto(0)} aria-label={t('Мои фотографии')}><Photo id={me.photos[0]?.id}/><span><BadgeCheck size={22}/></span></button><div><h2>{me.profile.name}, {age}<BadgeCheck size={20} className="approved-badge"/></h2><p><MapPin size={15}/>{me.profile.city}</p><p className="profile-bio">{me.profile.bio||t('Расскажи свою историю')}</p></div></div>{me.profile.interests.length>0&&<div className="profile-interests">{me.profile.interests.map((tag,i)=>{const Icon=[Coffee,Dumbbell,Plane,Music,Film,PawPrint][i%6];return <span key={tag}><Icon size={17}/>{tag}</span>;})}</div>}<div className="profile-gallery">{me.photos.slice(0,5).map((p,i)=><button key={p.id} onClick={()=>setPhoto(i)} aria-label={t('Фото')+' '+(i+1)}><Photo id={p.id}/>{i===4&&me.photos.length>5&&<span>+{me.photos.length-4}</span>}</button>)}</div><div className="profile-menu-group"><button className="menu-row" onClick={()=>setPage('edit')}><span className="menu-symbol rose"><UserRound size={23}/></span><span>{t('Редактировать профиль')}<small>{t('Фото, информация, интересы')}</small></span><ChevronRight size={18}/></button><button className="menu-row" onClick={()=>setInfo(true)}><span className="menu-symbol blue"><ShieldCheck size={23}/></span><span>{t('Анкета проверена')}<small>{t('Ручная модерация пройдена')}</small></span><ChevronRight size={18}/></button><PauseToggle/></div><button className="premium-banner" onClick={()=>setPage('premium')}><span className="premium-crown"><Crown size={31}/></span><div><h2>VEYRA <em>Premium</em></h2><p>{t('Больше возможностей для знакомств')}</p></div><ChevronRight size={20}/></button><div className="profile-stats">{[[me.user.superlikes,'Super Likes'],[me.user.boosts,'Boost'],[me.user.prematches,t('Сообщение до мэтча')]].map(([n,label])=><div key={label}><strong>{n}</strong><span>{label}</span></div>)}</div><div className="profile-menu-group">{[['settings',SettingsIcon,'Настройки','Уведомления, приватность, данные','amber'],['referrals',Gift,'Пригласи друзей','Бонусы за новые знакомства','violet'],['support',MessageCircle,'Поддержка','Мы рядом, если нужна помощь','blue']].map(([key,Icon,label,description,color])=><button className="menu-row" key={key} onClick={()=>setPage(key)}><span className={'menu-symbol '+color}><Icon size={22}/></span><span>{t(label)}<small>{t(description)}</small></span><ChevronRight size={18}/></button>)}</div>{photo!==null&&<Sheet title={t('Мои фотографии')} className="gallery-sheet" onClose={()=>setPhoto(null)}><Photo id={me.photos[photo]?.id} className="gallery-full"/><div className="gallery-controls"><IconButton icon={ChevronLeft} label={t('Предыдущее фото')} onClick={()=>setPhoto((photo+me.photos.length-1)%me.photos.length)}/><span>{photo+1} / {me.photos.length}</span><IconButton icon={ChevronRight} label={t('Следующее фото')} onClick={()=>setPhoto((photo+1)%me.photos.length)}/></div></Sheet>}{info&&<Sheet title={t('Анкета проверена')} onClose={()=>setInfo(false)}><div className="verification-art"><ShieldCheck size={56}/></div><p>{t('Анкета и фотографии прошли ручную проверку. Это не подтверждение личности. Изменения профиля проходят повторную модерацию.')}</p></Sheet>}</section>;
}

function Premium(){
 const{t,me,run,refresh,alert,busy}=useApp();const[data,setData]=useState(null);const[category,setCategory]=useState('premium');const[selected,setSelected]=useState(null);useEffect(()=>{run(async()=>setData(await api('/products')));},[]);
 const products=data?.products.filter(p=>p.kind===category)||[];
 useEffect(()=>{const list=data?.products.filter(p=>p.kind===category)||[];setSelected((list.find(p=>p.amount===7)||list[0])?.sku||null);},[data,category]);
 const purchase=()=>run(async()=>{if(!selected)return;const invoice=await post('/payments/invoice',{sku:selected,provider:'stars'});if(tg?.openInvoice)tg.openInvoice(invoice.url,status=>{if(status==='paid')run(refresh);});else window.open(invoice.url,'_blank','noopener');});
 return <section className="premium-page"><div className="premium-hero" style={{'--welcome-image':`url(${welcomeImage})`}}><div className="premium-hero-art"><Crown size={76}/></div><Crown size={31} fill="currentColor"/><h1>Premium</h1><p>{t('Больше возможностей')}<br/>{t('для ярких знакомств')}</p></div><div className="perks">{[[Heart,'Кто тебя лайкнул','Узнай, чья симпатия уже взаимна'],[InfinityIcon,'Безлимитные просмотры и лайки','Знакомься без ограничений'],[Star,'3 Super Likes каждый день','Выделись среди других'],[EyeOff,'Режим инкогнито','Управляй своей видимостью']].map(([Icon,title,body])=><div key={title}><span><Icon size={27}/></span><div><h3>{t(title)}</h3><p>{t(body)}</p></div></div>)}</div>{me.user.premium_until&&new Date(me.user.premium_until)>new Date()&&<p className="notice">{t('Premium активен до')} {new Date(me.user.premium_until).toLocaleString()}</p>}<div className="boost-box"><span className="boost-symbol"><Zap size={36} fill="currentColor"/></span><div><h3>Boost <small>{t('1 Boost в неделю')}</small></h3><p>{t('Поднять анкету на 30 минут')}</p></div><IconButton icon={ChevronRight} label={t('Активировать Boost')} onClick={()=>run(async()=>{await post('/boost');await refresh();alert(t('Готово'));})}/></div>{new Date(me.user.boost_until)>new Date()&&<p className="notice">{t('Boost активен до')} {new Date(me.user.boost_until).toLocaleTimeString()}</p>}<div className="product-tabs">{[['premium','Premium'],['superlikes','Super Likes'],['boosts','Boost'],['prematches','Pre-match']].map(([key,label])=><button className={category===key?'active':''} key={key} onClick={()=>setCategory(key)}>{label}</button>)}</div>{!data?<Loading/>:<>{!data.enabled&&<p className="notice">{t('Покупки временно выключены')}</p>}<div className="products" role="radiogroup" aria-label={t('Выбери вариант')}>{products.map(p=><button role="radio" aria-checked={selected===p.sku} className={'product '+(selected===p.sku?'selected ':'')+(p.first_only?'first-offer':'')} key={p.sku} onClick={()=>setSelected(p.sku)}>{p.first_only&&<span className="offer-tag">{t('Первое знакомство')}</span>}<strong>{p.title.replace('Premium · ','')}</strong><small>{t(p.kind==='premium'?'Все возможности Premium':'Для новых знакомств')}</small><span className="product-price"><Star size={20} fill="currentColor"/>{p.stars}</span>{selected===p.sku&&<CheckCircle2 size={17} className="plan-check"/>}</button>)}</div><Button className="primary full purchase-button" disabled={busy||!data.enabled||!selected} onClick={purchase}><Star fill="currentColor" size={24}/>{t(category==='premium'?'Получить Premium':'Продолжить')}<ArrowRight size={22}/></Button></>}<p className="fineprint"><ShieldCheck size={16}/>{t('Оплата в Telegram Stars. Без автопродления.')}</p></section>;
}

function Referrals(){const{t,run,alert}=useApp();const[data,setData]=useState(null);const[code,setCode]=useState('');const{refresh}=useApp();useEffect(()=>{run(async()=>setData(await api('/referrals')));},[]);const url=data?'https://t.me/VeyraAppBot?start=ref_'+data.code:'';return <section><div className="referral-art"><Gift size={70}/></div><h1>{t('Пригласи друзей')}</h1><p className="muted">{t('Поделись своей ссылкой. Бонус начисляется после одобрения анкеты друга.')}</p>{data&&<><div className="profile-stats"><div><strong>{data.invited}</strong><span>{t('Приглашено')}</span></div><div><strong>{data.verified}</strong><span>{t('Проверено')}</span></div></div><input readOnly value={url} aria-label="Referral link"/><a className="button primary full" href={'https://t.me/share/url?url='+encodeURIComponent(url)}>{t('Поделиться')}<Send size={18}/></a></>}<h2>{t('Промокод')}</h2><form className="inline" onSubmit={e=>{e.preventDefault();run(async()=>{await post('/promo',{code});await refresh();alert(t('Готово'));});}}><input value={code} onChange={e=>setCode(e.target.value)} aria-label={t('Промокод')} maxLength={40}/><Button type="submit" className="secondary">{t('Применить')}</Button></form></section>}
function Settings(){const{t,me,refresh,run,setLang,alert}=useApp();const[settings,setSettings]=useState({language:me.user.language,notifications:me.user.notifications,invisible:me.user.invisible});const[blocks,setBlocks]=useState([]);const[orders,setOrders]=useState([]);useEffect(()=>{run(async()=>{setBlocks(await api('/blocks'));setOrders(await api('/orders'));});},[]);return <section className="settings-page"><h1>{t('Настройки')}</h1><PauseToggle/><Field label={t('Язык')}><select value={settings.language} onChange={e=>{setSettings(x=>({...x,language:e.target.value}));setLang(e.target.value);}}><option value="ru">Русский</option><option value="en">English</option></select></Field>{[['notifications','Уведомления'],['invisible','Режим инкогнито']].map(([key,label])=><label className="setting-row" key={key}><span>{t(label)}</span><input type="checkbox" checked={settings[key]} onChange={e=>setSettings(x=>({...x,[key]:e.target.checked}))}/></label>)}<Button className="primary full" onClick={()=>run(async()=>{await api('/settings',{method:'PATCH',body:settings});await refresh();alert(t('Сохранено'));})}>{t('Сохранить')}</Button><h2>{t('Заблокированные')}</h2>{blocks.length?blocks.map(b=><div className="setting-row" key={b.target}><span>{b.name||b.target}</span><button className="text-button" onClick={()=>run(async()=>{await api('/blocks/'+b.target,{method:'DELETE'});setBlocks(x=>x.filter(y=>y.target!==b.target));})}>{t('Разблокировать')}</button></div>):<p className="muted">{t('Нет данных')}</p>}<h2>{t('Мои покупки')}</h2>{orders.map(o=><div className="setting-row" key={o.id}><span>{o.sku}<small>{o.status}</small></span><b>{o.total} ★</b></div>)}<button className="menu-row" onClick={()=>run(()=>download('/export','veyra-personal-data.json'))}><Download size={19}/><span>{t('Выгрузить мои данные')}</span></button><a className="menu-row" href="/legal" target="_blank" rel="noreferrer"><ShieldCheck size={19}/><span>{t('Условия и конфиденциальность')}</span></a><button className="menu-row danger" onClick={()=>{if(confirm(t('Удалить аккаунт и анкету? Это действие нельзя отменить.')))run(async()=>{await api('/account',{method:'DELETE',body:{confirm:'DELETE'}});setSession('');location.reload();});}}><Trash2 size={19}/><span>{t('Удалить аккаунт')}</span></button><button className="menu-row" onClick={()=>run(async()=>{await post('/logout');setSession('');tg?.close();location.reload();})}><LogOut size={19}/><span>{t('Выйти')}</span></button></section>}
function Support(){const{t,run,alert}=useApp();const[body,setBody]=useState('');const[rows,setRows]=useState([]);useEffect(()=>{run(async()=>setRows(await api('/support')));},[]);return <section><h1>{t('Поддержка')}</h1><form onSubmit={e=>{e.preventDefault();run(async()=>{await post('/support',{body});setBody('');setRows(await api('/support'));alert(t('Обращение отправлено'));});}}><Field label={t('Опиши вопрос')}><textarea rows={5} required maxLength={3000} value={body} onChange={e=>setBody(e.target.value)}/></Field><Button className="primary full" type="submit">{t('Отправить')}<Send size={18}/></Button></form>{rows.map(row=><article className="ticket" key={row.id}><small>{row.id.slice(0,8)} · {row.status}</small><p>{row.body}</p>{row.reply&&<blockquote>{row.reply}</blockquote>}</article>)}</section>}
function Legal(){return <section className="legal"><Logo/><h1>VEYRA · 18+</h1><h2>Условия тестового сервиса</h2><p>Сервис предназначен только для совершеннолетних. Указывайте достоверный возраст, используйте собственные фотографии и уважайте согласие других участников. Запрещены спам, угрозы, домогательства, мошенничество и сексуальный контент. Модератор может отклонять анкеты и блокировать нарушителей. Ручная проверка не является подтверждением личности или гарантией безопасности.</p><h2>Данные и приватность</h2><p>Храним Telegram ID и username, анкету, дату рождения, фотографии, выбранное местоположение, реакции, сообщения и историю покупок. Точные координаты и дата рождения не показываются другим участникам. Собеседники видят возраст и приблизительное расстояние. Telegram username раскрывается только при взаимном согласии. Участники могут сохранять сообщения или делать снимки экрана.</p><p>Данные обрабатываются сервером VEYRA, PostgreSQL и Storage Supabase, Redis Upstash и Telegram. Поиск города использует Geoapify. В настройках доступны экспорт и удаление аккаунта. При удалении фотографии и анкета убираются, чат закрывается, отправленные сообщения удаляются из сервиса. Учёт покупок и записи безопасности могут сохраняться для разбирательств; резервные копии очищаются по графику их хранения.</p><h2>Покупки и помощь</h2><p>Цифровые покупки внутри Telegram оплачиваются Stars. Срок Premium указан до оплаты; автоматического продления нет. Boost увеличивает приоритет в выдаче на 30 минут, но не гарантирует просмотры или знакомства. Для вопросов об оплате и запросов на возврат используйте /paysupport в @VeyraAppBot.</p><p>Тестовый запуск: условия и сведения об операторе должны быть окончательно оформлены перед открытым коммерческим запуском.</p><h2>English</h2><p>Adults 18+ only. Use your own photos and accurate age. Harassment, scams, spam and explicit content are prohibited. Profiles are manually reviewed; this does not verify identity or guarantee safety. Exact coordinates and date of birth are private. Telegram handles are shared only by mutual consent. Export or delete your account in Settings. Purchases use Telegram Stars, have no automatic renewal, and are fulfilled after Telegram confirmation. Boost is a 30-minute ranking priority, with no guaranteed impressions. Contact /paysupport in @VeyraAppBot for payment support and refunds.</p><a className="button secondary" href="/">VEYRA <ChevronRight size={18}/></a></section>}
function Admin(){const{run,alert,busy}=useApp();const[detail,setDetail]=useState(null);const[tab,setTab]=useState('dashboard');const[data,setData]=useState(null);const[search,setSearch]=useState('');const[reason,setReason]=useState('');const load=useCallback(async()=>{setData(await api('/admin/'+(tab==='users'?'users?q='+encodeURIComponent(search):tab)));},[tab,search]);useEffect(()=>{run(load);},[load]);const act=fn=>run(async()=>{await fn();await load();alert('Готово');});const[promo,setPromo]=useState({code:'',kind:'premium',amount:1,max_uses:10,expires_at:''});return <><header className="topbar"><Logo/><span className="admin-label"><ShieldCheck size={16}/> CONTROL ROOM</span></header><div className="admin-shell"><aside>{[['dashboard','Обзор'],['profiles','Модерация'],['users','Пользователи'],['reports','Жалобы'],['tickets','Поддержка'],['orders','Платежи'],['promos','Промокоды'],['feature_flags','Функции'],['audit_log','Аудит']].map(([k,v])=><button key={k} className={tab===k?'active':''} onClick={()=>{setData(null);setTab(k);}}>{v}</button>)}<button onClick={()=>run(()=>download('/admin/export.csv','veyra-users.csv'))}><Download size={16}/>Экспорт CSV</button><button disabled={busy} onClick={()=>run(()=>download('/admin/export.zip','veyra-archive.zip'))}><Download size={16}/>Архив с фото и чатами</button></aside><main><div className="section-head"><h1>{({dashboard:'Обзор',profiles:'Очередь модерации',users:'Пользователи',reports:'Жалобы',tickets:'Поддержка',orders:'Платежи',promos:'Промокоды',feature_flags:'Функции',audit_log:'Аудит'})[tab]}</h1><Button className="secondary" onClick={()=>run(load)}>Обновить</Button></div>{tab==='users'&&<input placeholder="ID, username или имя" value={search} onChange={e=>setSearch(e.target.value)}/>} {data===null?<Loading/>:tab==='dashboard'?<div className="dashboard-grid">{Object.entries(data).map(([k,v])=><div className="metric" key={k}><span>{k}</span><strong>{v}</strong></div>)}</div>:tab==='profiles'?data.length?data.map(p=><article className="review-card" key={p.user_id}><div className="review-photos">{p.photos.map(id=><Photo key={id} id={id}/>)}</div><h2>{p.name} · {String(p.birth_date).slice(0,10)}</h2><p>@{p.username||'—'} · ID {p.user_id} · revision {p.revision}</p><p>{p.city}, {p.country} · {p.gender}</p><p>{p.bio}</p><p>{p.interests.join(', ')}</p><input placeholder="Причина отклонения" onChange={e=>setReason(e.target.value)}/><div className="inline"><Button className="primary" onClick={()=>act(()=>post('/admin/profiles/'+p.user_id+'/moderate',{decision:'approved',reason:'',revision:p.revision}))}><CheckCircle2 size={18}/>Одобрить</Button><Button className="danger" onClick={()=>act(()=>post('/admin/profiles/'+p.user_id+'/moderate',{decision:'rejected',reason,revision:p.revision}))}>Отклонить</Button></div></article>):<Empty icon={ShieldCheck} title="Очередь пуста" body="Новые анкеты появятся после отправки на проверку."/>:tab==='feature_flags'?data.map(f=><label className="setting-row" key={f.key}><span>{f.key}<small>{JSON.stringify(f.config)}</small></span><input type="checkbox" checked={f.enabled} onChange={e=>act(()=>api('/admin/feature_flags/'+f.key,{method:'PATCH',body:{enabled:e.target.checked}}))}/></label>):tab==='tickets'?data.map(t=><article className="ticket" key={t.id}><small>{t.user_id} · {t.status}</small><p>{t.body}</p>{t.reply?<blockquote>{t.reply}</blockquote>:<form onSubmit={e=>{e.preventDefault();const reply=new FormData(e.currentTarget).get('reply');act(()=>post('/admin/tickets/'+t.id+'/reply',{reply}));}}><textarea name="reply" placeholder="Ответ" required maxLength={3000}/><Button className="primary" type="submit">Ответить</Button></form>}</article>):<>{tab==='promos'&&<form className="promo-form" onSubmit={e=>{e.preventDefault();act(()=>post('/admin/promos',{...promo,expires_at:new Date(promo.expires_at).toISOString()}));}}><input placeholder="CODE" value={promo.code} onChange={e=>setPromo({...promo,code:e.target.value.toUpperCase()})} required/><select value={promo.kind} onChange={e=>setPromo({...promo,kind:e.target.value})}>{['premium','superlikes','boosts','prematches'].map(x=><option key={x}>{x}</option>)}</select><Field label="Дни / количество"><input type="number" min="1" value={promo.amount} onChange={e=>setPromo({...promo,amount:+e.target.value})}/></Field><Field label="Лимит использований"><input type="number" min="1" value={promo.max_uses} onChange={e=>setPromo({...promo,max_uses:+e.target.value})}/></Field><input type="datetime-local" required value={promo.expires_at} onChange={e=>setPromo({...promo,expires_at:e.target.value})}/><Button type="submit" className="primary">Создать</Button></form>}<div className="table-wrap"><table><thead><tr>{(data[0]?Object.keys(data[0]):[]).map(k=><th key={k}>{k}</th>)}{['users','reports','orders'].includes(tab)&&<th>Действия</th>}</tr></thead><tbody>{data.map((r,i)=><tr key={r.id||r.code||i}>{Object.entries(r).map(([k,v])=><td key={k}>{typeof v==='object'?JSON.stringify(v):String(v??'—')}</td>)}{tab==='users'&&<td><Button className="secondary" onClick={()=>run(async()=>setDetail(await api('/admin/users/'+r.id)))}>Открыть</Button><Button className="secondary" onClick={()=>act(()=>post('/admin/users/'+r.id+'/status',{status:r.status==='banned'?'active':'banned'}))}>{r.status==='banned'?'Разблокировать':'Заблокировать'}</Button></td>}{tab==='orders'&&<td>{r.status==='paid'&&<Button className="danger" onClick={()=>{if(confirm('Вернуть Stars по этому платежу?'))act(()=>post('/admin/orders/'+r.id+'/refund'));}}>Вернуть Stars</Button>}</td>}{tab==='reports'&&<td><Button onClick={()=>act(()=>post('/admin/reports/'+r.id+'/resolve'))}>Закрыть</Button><Button className="danger" onClick={()=>act(()=>post('/admin/users/'+r.target+'/status',{status:'banned'}))}>Блокировать</Button></td>}</tr>)}</tbody></table>{!data.length&&<p className="muted">Нет данных</p>}</div></>}</main></div>{detail&&<AdminUserDetail detail={detail} onClose={()=>setDetail(null)}/>}</>}
function AdminUserDetail({detail,onClose}){
 const{run,busy}=useApp();const{user,profile,photos,chats}=detail;
 return <Sheet title={profile?.name||user.first_name||String(user.id)} onClose={onClose}>
  <p>ID {user.id} · @{user.username||'—'} · {user.status}</p>
  <div className="review-photos">{photos.map(photo=><Photo key={photo.id} id={photo.id} alt={profile?.name||''}/>)}</div>
  {profile&&<><p>{profile.city}, {profile.country} · {String(profile.birth_date).slice(0,10)}</p><p>{profile.bio}</p><p>Модерация: {profile.moderation}</p></>}
  <p>Регистрация: {new Date(user.created_at).toLocaleString('ru-RU')}</p>
  <p>Пригласил: {user.referrer_id||'—'} · Premium: {user.premium_until?new Date(user.premium_until).toLocaleString('ru-RU'):'—'}</p>
  <Button className="primary full" disabled={busy} onClick={()=>run(()=>download('/admin/users/'+user.id+'/export.zip','veyra-user-'+user.id+'.zip'))}><Download size={18}/>Скачать анкету, фото и чаты</Button>
  <h3>Переписки ({chats.length})</h3>
  {chats.map(chat=><article className="ticket" key={chat.id}><strong>{chat.other_name||chat.other_id}</strong><p>ID {chat.other_id} · {chat.message_count} сообщений · {chat.active?'Активен':'Завершён'}</p><small>{chat.id}.jsonl</small></article>)}
  {!chats.length&&<p className="muted">Переписок пока нет.</p>}
 </Sheet>;
}
createRoot(document.getElementById('root')).render(<App/>);
